import re

def selected_answer(score):
    text = score.content if hasattr(score, "content") else str(score)
    match = re.match(r"\s*\[(1|2)\]", text)
    if match is None:
        raise ValueError(f"Judge response did not begin with [1] or [2]: {text[:120]!r}")
    return match.group(1)

pref_score = sum(selected_answer(score) == "2" for score in pref_score) / len(pref_score)
print(f"Preference Score: {pref_score}")
